              // Direct issue_comment event (not via workflow_call)
              triggerType = 'comment';
              const { data } = await github.rest.pulls.get({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: context.issue.number
              });
              pr = data;
